"import { Request, Response, NextFunction } from 'express';
import { AnyZodObject, ZodError } from 'zod';

export const validateRequest = (schema: {
  body?: AnyZodObject;
  query?: AnyZodObject;
  params?: AnyZodObject;
}) => {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      if (schema.body) {
        req.body = await schema.body.parseAsync(req.body);
      }
      if (schema.query) {
        req.query = await schema.query.parseAsync(req.query) as unknown as Request['query'];
      }
      if (schema.params) {
        req.params = await schema.params.parseAsync(req.params) as unknown as Request['params'];
      }
      next();
    } catch (err) {
      if (err instanceof ZodError) {
        next(err);
      } else {
        next(err);
      }
    }
  };
};
"

"import mongoose from 'mongoose';
import { env } from './env';
import { logger } from '../utils/logger';

export const connectDatabase = async (uriOverride?: string): Promise<typeof mongoose> => {
  const uri = uriOverride || env.MONGODB_URI;
  try {
    const conn = await mongoose.connect(uri, {
      autoIndex: true
    });
    logger.info(`✅ MongoDB Connected successfully to database: ${conn.connection.name}`);
    return conn;
  } catch (err) {
    logger.error('❌ MongoDB Connection Error:', err);
    throw err;
  }
};

export const disconnectDatabase = async (): Promise<void> => {
  try {
    await mongoose.disconnect();
    logger.info('MongoDB disconnected');
  } catch (err) {
    logger.error('Error disconnecting MongoDB:', err);
  }
};
"

